# Terraform: Refactored Dev/Prod via `for_each` Module

## Directory Layout

```
terraform/
├── main.tf
├── variables.tf
├── outputs.tf
├── moved.tf
├── backend.tf
├── dev.tfvars
├── prod.tfvars
└── modules/
    └── env/
        ├── main.tf
        ├── variables.tf
        └── outputs.tf
```

---

## `terraform/main.tf`

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws  = { source = "hashicorp/aws",  version = "~> 5.0" }
    kubernetes = { source = "hashicorp/kubernetes", version = "~> 2.25" }
  }
}

locals {
  envs = {
    dev = {
      name     = "dev"
      region   = "us-east-1"
      vpc_cidr = "10.0.0.0/16"
      eks = {
        instance_type = "t3.medium"
        node_count    = 2
      }
      s3 = {
        enable_crr = false
        crr_target_region = ""
      }
      rds = {
        instance_class     = "db.t3.micro"
        multi_az           = false
        storage_encrypted  = false
      }
      iam = {
        type = "user"  # "user" | "oidc_role"
      }
      https = {
        type          = "internal_alb"  # "internal_alb" | "cloudfront"
        acm_region    = "us-east-1"
        domain        = "dev.example.com"
      }
    }
    prod = {
      name     = "prod"
      region   = "us-east-2"
      vpc_cidr = "10.1.0.0/16"
      eks = {
        instance_type = "t3.large"
        node_count    = 4
      }
      s3 = {
        enable_crr          = true
        crr_target_region   = "us-west-2"
      }
      rds = {
        instance_class     = "db.t3.medium"
        multi_az           = true
        storage_encrypted  = true
      }
      iam = {
        type                = "oidc_role"
        oidc_provider_arn  = var.prod_oidc_provider_arn
        oidc_service_account = "app"
      }
      https = {
        type          = "cloudfront"
        acm_region    = "us-east-2"
        domain        = "prod.example.com"
      }
    }
  }
}

module "env" {
  source = "./modules/env"

  for_each = local.envs

  name     = each.value.name
  region   = each.value.region
  vpc_cidr = each.value.vpc_cidr

  eks_instance_type = each.value.eks.instance_type
  eks_node_count    = each.value.eks.node_count

  s3_enable_crr         = each.value.s3.enable_crr
  s3_crr_target_region  = each.value.s3.crr_target_region

  rds_instance_class    = each.value.rds.instance_class
  rds_multi_az          = each.value.rds.multi_az
  rds_storage_encrypted = each.value.rds.storage_encrypted

  iam_type                 = each.value.iam.type
  iam_oidc_provider_arn    = lookup(each.value.iam, "oidc_provider_arn", "")
  iam_oidc_service_account = lookup(each.value.iam, "oidc_service_account", "")

  https_type        = each.value.https.type
  https_acm_region  = each.value.https.acm_region
  https_domain      = each.value.https.domain

  # SOPS-encrypted via tfvars (see dev.tfvars / prod.tfvars)
  db_connection_string = var.db_connection_strings[each.key]

  tags = {
    Environment = each.key
    ManagedBy   = "terraform"
  }
}
```

---

## `terraform/variables.tf`

```hcl
variable "db_connection_strings" {
  description = "SOPS-encrypted DB connection strings per environment. Encrypted with sops using the team age key."
  type        = map(string)
  sensitive   = true
  default     = {}
}

variable "prod_oidc_provider_arn" {
  description = "ARN of the OIDC IdP provider for prod (EKS cluster OIDC)."
  type        = string
  default     = ""
}
```

---

## `terraform/outputs.tf`

```hcl
output "env_endpoints" {
  description = "Per-environment connection endpoints."
  value = {
    for key, mod in module.env : key => {
      eks_endpoint   = mod.eks_endpoint
      rds_endpoint   = mod.rds_endpoint
      https_domain   = mod.https_domain
      s3_bucket_name = mod.s3_bucket_name
    }
  }
}
```

---

## `terraform/moved.tf`

```hcl
# ─────────────────────────────────────────────────────────────
# State moves: explicit module calls → for_each module
# These are zero-diff; Terraform re-addresses resources in
# state without any plan action.
# ─────────────────────────────────────────────────────────────

# DEV
moved {
  from = module.dev.aws_vpc.main
  to   = module.env["dev"].aws_vpc.main
}
moved {
  from = module.dev.aws_eks_cluster.this
  to   = module.env["dev"].aws_eks_cluster.this
}
moved {
  from = module.dev.aws_eks_node_group.workers
  to   = module.env["dev"].aws_eks_node_group.workers
}
moved {
  from = module.dev.aws_s3_bucket.assets
  to   = module.env["dev"].aws_s3_bucket.assets
}
moved {
  from = module.dev.aws_db_instance.primary
  to   = module.env["dev"].aws_db_instance.primary
}
moved {
  from = module.dev.aws_iam_user.service
  to   = module.env["dev"].aws_iam_user.service
}
moved {
  from = module.dev.aws_alb.this
  to   = module.env["dev"].aws_alb.this
}
moved {
  from = module.dev.aws_alb_listener.https
  to   = module.env["dev"].aws_alb_listener.https
}

# PROD
moved {
  from = module.prod.aws_vpc.main
  to   = module.env["prod"].aws_vpc.main
}
moved {
  from = module.prod.aws_eks_cluster.this
  to   = module.env["prod"].aws_eks_cluster.this
}
moved {
  from = module.prod.aws_eks_node_group.workers
  to   = module.env["prod"].aws_eks_node_group.workers
}
moved {
  from = module.prod.aws_s3_bucket.assets
  to   = module.env["prod"].aws_s3_bucket.assets
}
moved {
  from = module.prod.aws_s3_bucket_replication_configuration.assets
  to   = module.env["prod"].aws_s3_bucket_replication_configuration.assets
}
moved {
  from = module.prod.aws_db_instance.primary
  to   = module.env["prod"].aws_db_instance.primary
}
moved {
  from = module.prod.aws_iam_role.service
  to   = module.env["prod"].aws_iam_role.service
}
moved {
  from = module.prod.aws_cloudfront_distribution.main
  to   = module.env["prod"].aws_cloudfront_distribution.main
}
moved {
  from = module.prod.aws_acm_certificate.main
  to   = module.env["prod"].aws_acm_certificate.main
}
```

