## `modules/env/main.tf`

```hcl
provider "aws" {
  region = var.region
}

# ─── Names ───────────────────────────────────────────────────

locals {
  name_prefix = "tf-${var.name}"
}

# ─── VPC (minimal – in production, reference shared VPC) ────

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true
  tags = merge(var.tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, 1)
  availability_zone       = "${var.region}a"
  map_public_ip_on_launch = true
  tags = { Name = "${local.name_prefix}-public-a" }
}

resource "aws_subnet" "private_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, 10)
  availability_zone = "${var.region}a"
  tags = { Name = "${local.name_prefix}-private-a" }
}

resource "aws_subnet" "private_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, 11)
  availability_zone = "${var.region}b"
  tags = { Name = "${local.name_prefix}-private-b" }
}

resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.main.id
  tags   = { Name = local.name_prefix }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.this.id
  }
  tags = { Name = "${local.name_prefix}-public" }
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

# ─── EKS ─────────────────────────────────────────────────────

resource "aws_eks_cluster" "this" {
  name     = local.name_prefix
  role_arn = aws_iam_role.eks_control_plane.arn
  version  = "1.29"

  vpc_config {
    subnet_ids = [
      aws_subnet.public_a.id,
      aws_subnet.private_a.id,
      aws_subnet.private_b.id,
    ]
    endpoint_public_access  = false
    endpoint_private_access = true
  }

  enabled_cluster_admin_access = true
  tags                         = merge(var.tags, { Name = local.name_prefix })
}

resource "aws_iam_role" "eks_control_plane" {
  name = "${local.name_prefix}-eks-cp"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action  = "sts:AssumeRole"
      Effect  = "Allow"
      Principal = {
        Service = "eks.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_role_policy_attachment" "eks_control_plane" {
  role       = aws_iam_role.eks_control_plane.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_eks_node_group" "workers" {
  cluster_name    = aws_eks_cluster.this.name
  node_group_name = "workers"
  node_role_arn   = aws_iam_role.eks_node_group.arn
  subnet_ids      = [
    aws_subnet.private_a.id,
    aws_subnet.private_b.id,
  ]

  instance_types = [var.eks_instance_type]

  scaling_config {
    desired_size = var.eks_node_count
    min_size     = var.eks_node_count
    max_size     = var.eks_node_count * 2
  }

  update_config {
    max_parallel_percentage   = 50
    max_unavailable_percentage = 10
  }

  tags = var.tags
}

resource "aws_iam_role" "eks_node_group" {
  name = "${local.name_prefix}-eks-ng"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action  = "sts:AssumeRole"
      Effect  = "Allow"
      Principal = {
        Service = "ec2.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_role_policy_attachment" "eks_node_group" {
  role       = aws_iam_role.eks_node_group.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
}

resource "aws_iam_role_policy_attachment" "eks_node_group_cni" {
  role       = aws_iam_role.eks_node_group.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
}

resource "aws_iam_role_policy_attachment" "eks_node_group_vpc_ro" {
  role       = aws_iam_role.eks_node_group.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
}

# ─── S3 ──────────────────────────────────────────────────────

resource "aws_s3_bucket" "assets" {
  bucket        = "${local.name_prefix}-assets"
  force_destroy = false
  tags          = merge(var.tags, { Name = "${local.name_prefix}-assets" })
}

resource "aws_s3_bucket_versioning" "assets" {
  bucket = aws_s3_bucket.assets.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "assets" {
  bucket = aws_s3_bucket.assets.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "assets" {
  bucket                  = aws_s3_bucket.assets.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# CRR – prod only
resource "aws_s3_bucket" "crr_target" {
  count = var.s3_enable_crr ? 1 : 0

  bucket = "${local.name_prefix}-assets-replica"
  force_destroy = false

  tags = merge(var.tags, { Name = "${local.name_prefix}-assets-replica" })
}

resource "aws_s3_bucket_replication_configuration" "assets" {
  count = var.s3_enable_crr ? 1 : 0

  role     = aws_iam_role.s3_replication.arn
  bucket   = aws_s3_bucket.assets.id

  rules {
    id     = "crr-${var.name}"
    status = "Enabled"

    destination {
      bucket        = "arn:aws:s3:::${aws_s3_bucket.crr_target[0].bucket}"
      storage_class = "STANDARD"

      account = data.aws_caller_identity.current.account_id
    }
  }
}

resource "aws_iam_role" "s3_replication" {
  count = var.s3_enable_crr ? 1 : 0

  name = "${local.name_prefix}-s3-replication"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action  = "sts:AssumeRole"
      Effect  = "Allow"
      Principal = {
        Service = "s3.amazonaws.com"
      }
    }]
  })
}

resource "aws_iam_role_policy" "s3_replication" {
  count = var.s3_enable_crr ? 1 : 0

  role = aws_iam_role.s3_replication[0].id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "s3:GetReplicationConfiguration",
        "s3:ListBucket",
        "s3:GetObjectVersion",
        "s3:ReplicateObject",
        "s3:ReplicateDelete",
        "s3:ReplicateTags",
      ]
      Resource = [
        aws_s3_bucket.assets.arn,
        "${aws_s3_bucket.assets.arn}/*",
      ]
    }, {
      Effect = "Allow"
      Action = [
        "s3:ReplicateObject",
        "s3:GetObjectVersion",
        "s3:PutObject",
        "s3:PutObjectLegalHold",
        "s3:PutObjectRetention",
        "s3:PutObjectTagging",
        "s3:PutObjectVersionTagging",
        "s3:AbortMultipartUpload",
      ]
      Resource = [
        aws_s3_bucket.crr_target[0].arn,
        "${aws_s3_bucket.crr_target[0].arn}/*",
      ]
    }]
  })
}

data "aws_caller_identity" "current" {}

# ─── RDS PostgreSQL ──────────────────────────────────────────

resource "aws_db_subnet_group" "primary" {
  name       = local.name_prefix
  subnet_ids = [
    aws_subnet.private_a.id,
    aws_subnet.private_b.id,
  ]
  tags = var.tags
}

resource "aws_security_group" "rds" {
  name   = "${local.name_prefix}-rds"
  vpc_id = aws_vpc.main.id
  tags   = var.tags

  ingress {
    description = "PostgreSQL from VPC"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_instance" "primary" {
  identifier              = local.name_prefix
  engine                  = "postgres"
  engine_version          = "15"
  instance_class          = var.rds_instance_class
  allocated_storage       = 20
  max_allocated_storage   = 100
  db_name                 = "app"
  username                = "app"
  password                = var.db_connection_string
  managed_master_password = true

  multi_az           = var.rds_multi_az
  storage_encrypted  = var.rds_storage_encrypted
  deletion_protection = true
  backup_retention_period = 14

  publicly_accessible    = false
  db_subnet_group_name   = aws_db_subnet_group.primary.name
  vpc_security_group_ids = [aws_security_group.rds.id]

  skip_final_snapshot = false
  final_snapshot_identifier = "${local.name_prefix}-final"

  apply_immediately = false
  tags              = var.tags
}

# ─── IAM (service account) ───────────────────────────────────

# Dev: IAM user with programmatic access
resource "aws_iam_user" "service" {
  count = var.iam_type == "user" ? 1 : 0

  name = "${local.name_prefix}-service"
  path = "/"
  tags = var.tags

  force_destroy = false
}

resource "aws_iam_access_key" "service" {
  count = var.iam_type == "user" ? 1 : 0

  user = aws_iam_user.service[0].name
}

resource "aws_iam_user_policy" "service" {
  count = var.iam_type == "user" ? 1 : 0

  user = aws_iam_user.service[0].name
  name = "${local.name_prefix}-service-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Sid    = "RDSAccess"
      Effect = "Allow"
      Action = [
        "rds-db:connect",
        "rds:DescribeDBInstances",
      ]
      Resource = [
        aws_db_instance.primary.arn,
        "arn:aws:rds-db:${var.region}:${data.aws_caller_identity.current.account_id}:dbuser:${aws_db_instance.primary.resource_id}/app",
      ]
    }, {
      Sid    = "S3Assets"
      Effect = "Allow"
      Action = [
        "s3:GetObject",
        "s3:PutObject",
        "s3:ListBucket",
      ]
      Resource = [
        aws_s3_bucket.assets.arn,
        "${aws_s3_bucket.assets.arn}/*",
      ]
    }]
  })
}

# Prod: OIDC trust role (least-privilege)
resource "aws_iam_role" "service" {
  count = var.iam_type == "oidc_role" ? 1 : 0

  name = "${local.name_prefix}-service"
  tags = var.tags

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect  = "Allow"
      Action  = "sts:AssumeRoleWithWebIdentity"
      Principal = {
        Federated = var.iam_oidc_provider_arn
      }
      Condition = {
        StringEquals = {
          "${replace(var.iam_oidc_provider_arn, "arn:aws:iam::${data.aws_caller_identity.current.account_id}:oidc-provider/", "")}:sub" = "system:serviceaccount:default:${var.iam_oidc_service_account}"
        }
      }
    }]
  })
}

resource "aws_iam_role_policy" "service" {
  count = var.iam_type == "oidc_role" ? 1 : 0

  role = aws_iam_role.service[0].name
  name = "${local.name_prefix}-service-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Sid    = "RDSAccess"
      Effect = "Allow"
      Action = [
        "rds-db:connect",
      ]
      Resource = [
        "arn:aws:rds-db:${var.region}:${data.aws_caller_identity.current.account_id}:dbuser:${aws_db_instance.primary.resource_id}/app",
      ]
    }, {
      Sid    = "S3Assets"
      Effect = "Allow"
      Action = [
        "s3:GetObject",
        "s3:PutObject",
      ]
      Resource = [
        "${aws_s3_bucket.assets.arn}/*",
      ]
    }]
  })
}

# ─── HTTPS Exposure ──────────────────────────────────────────

# Shared: ACM certificate (needed for both ALB and CloudFront)
resource "aws_acm_certificate" "main" {
  domain_name               = var.https_domain
  validation_method         = "DNS"
  deletion_protection       = true

  lifecycle {
    provisioner "local-exec" {
      command     = "aws --region ${var.https_acm_region} acm describe-certificate --certificate-arn ${self.arn} --query 'Certificate.DomainValidationOptions' --output json | jq -r '.[0].ResourceRecord' > /tmp/acm_rr.json"
      interpreter = ["/bin/bash", "-c"]
    }
  }
}

# Dev: Internal ALB
resource "aws_alb" "this" {
  count = var.https_type == "internal_alb" ? 1 : 0

  name               = local.name_prefix
  internal           = true
  load_balancer_type = "application"
  subnets            = [
    aws_subnet.private_a.id,
    aws_subnet.private_b.id,
  ]
  security_groups    = [aws_security_group.alb.id]
  tags               = var.tags
}

resource "aws_security_group" "alb" {
  count = var.https_type == "internal_alb" ? 1 : 0

  name   = "${local.name_prefix}-alb"
  vpc_id = aws_vpc.main.id
  tags   = var.tags

  ingress {
    description = "HTTPS from VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_alb_listener" "https" {
  count = var.https_type == "internal_alb" ? 1 : 0

  load_balancer_arn = aws_alb.this[0].arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-2016-08"
  certificate_arn   = aws_acm_certificate.main.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_alb_target_group.this[0].arn
  }
}

resource "aws_alb_target_group" "this" {
  count = var.https_type == "internal_alb" ? 1 : 0

  name     = "${local.name_prefix}-tg"
  port     = 8080
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id
  tags     = var.tags
}

# Prod: CloudFront
resource "aws_cloudfront_distribution" "main" {
  count = var.https_type == "cloudfront" ? 1 : 0

  enabled             = true
  default_root_object = "index.html"

  origin {
    domain_name              = aws_s3_bucket.assets.bucket_regional_domain_name
    origin_id                = "s3-${var.name}"
    custom_origin_config {
      http_port                = 443
      https_port               = 443
      origin_protocol_policy   = "https-only"
      origin_ssl_protocols     = ["TLSv1.2"]
    }
  }

  default_cache_behavior {
    allowed_methods  = ["GET", "HEAD"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "s3-${var.name}"
    viewer_protocol_policy = "redirect-to-https"
    compress           = true
    min_ttl            = 0
    default_ttl        = 3600
    max_ttl            = 86400

    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    acm_certificate_arn      = aws_acm_certificate.main.arn
    ssl_support_method       = "sni-only"
    minimum_protocol_version = "TLSv1.2"
  }

  aliases = [var.https_domain]

  price_class = "PriceClass_100"
  tags        = var.tags
}

# ─── Kubernetes Provider (for future in-cluster resources) ──

provider "kubernetes" {
  host     = aws_eks_cluster.this.endpoint
  cluster_ca_certificate = base64decode(aws_eks_cluster.this.certificate_authority[0].data)

  exec {
    api_version = "client.authentication.k8s.io/v1beta1"
    args        = ["eks", "get-token", "--cluster-name", aws_eks_cluster.this.name]
    command     = "aws"
  }
}
